/**
 * Gem cuts and gem materials: the single source for proportions, carat↔mm conversion and
 * optical constants. Geometry (facets) is generated by @pave/kernel from these proportions;
 * appearance by @pave/render from the optical constants.
 *
 * Conventions: `length` ≥ `width` are the girdle outline in mm, `depth` is table-to-culet.
 * Percentages are fractions of `width` (the industry "average diameter" for rounds).
 */

export type GemOutline =
  | 'round'
  | 'oval'
  | 'square'
  | 'rect'
  | 'cushion'
  | 'pear'
  | 'marquise'
  | 'heart'
  | 'triangle'

export type FacetStyle = 'brilliant' | 'step' | 'mixed' | 'cabochon'

export interface GemCut {
  label: string
  outline: GemOutline
  style: FacetStyle
  /** Default and allowed length:width ratio. */
  lw: { default: number; min: number; max: number }
  /** Corner treatment for square/rect outlines: fraction of width that is cut (0 = sharp). */
  cornerCut: number
  /** Total depth / width. */
  depthPct: number
  tablePct: number
  /** Crown height / width and pavilion depth / width (girdle is the remainder). */
  crownPct: number
  pavilionPct: number
  girdlePct: number
  /**
   * Diamond weight-estimation factors: ct = L × W × D × factor (GIA estimation formulas).
   * Multiple entries are interpolated by length:width ratio.
   */
  caratFactor: ReadonlyArray<readonly [lw: number, factor: number]>
}

const cut = (c: GemCut): GemCut => c

