export type GemCutId = keyof typeof GEM_CUTS
export const GEM_CUT_IDS = Object.keys(GEM_CUTS) as [GemCutId, ...GemCutId[]]

export interface GemMaterial {
  label: string
  /** Specific gravity (g/cm³). Diamond = 3.52 is the reference for carat factors. */
  sg: number
  /** Refractive index (mean of the range for birefringent stones). */
  ri: number
  /** Dispersion (B–G interval). */
  dispersion: number
  /** sRGB body colour for swatches and as the default transmission tint. */
  color: string
  /** Opaque / translucent stones are shaded as surfaces rather than refracted. */
  opaque?: boolean
  mohs: number
}

const g = (
  label: string,
  sg: number,
  ri: number,
  dispersion: number,
  color: string,
  mohs: number,
  opaque?: boolean,
): GemMaterial => ({ label, sg, ri, dispersion, color, mohs, ...(opaque ? { opaque } : {}) })

