export type GemMaterialId = keyof typeof GEM_MATERIALS
export const GEM_MATERIAL_IDS = Object.keys(GEM_MATERIALS) as [GemMaterialId, ...GemMaterialId[]]

export interface GemDims {
  length: number
  width: number
  depth: number
}

const DIAMOND_SG = 3.52

function caratFactor(c: GemCut, lw: number): number {
  const table = c.caratFactor
  const first = table[0]!
  if (lw <= first[0]) return first[1]
  for (let i = 1; i < table.length; i++) {
    const [r1, f1] = table[i]!
    const [r0, f0] = table[i - 1]!
    if (lw <= r1) return f0 + ((lw - r0) / (r1 - r0)) * (f1 - f0)
  }
  return table[table.length - 1]![1]
}

/** Full dimensions from a girdle width (and optional length:width ratio). */
export function gemDims(cutId: GemCutId, width: number, lw?: number): GemDims {
  const c: GemCut = GEM_CUTS[cutId]
  const ratio = Math.min(c.lw.max, Math.max(c.lw.min, lw ?? c.lw.default))
  return { length: width * ratio, width, depth: width * c.depthPct }
}

/** Estimated carat weight for a cut of the given dimensions and material. */
export function gemCarat(
  cutId: GemCutId,
  dims: GemDims,
  material: GemMaterialId = 'diamond',
): number {
  const c: GemCut = GEM_CUTS[cutId]
  const f = caratFactor(c, dims.length / dims.width)
  return dims.length * dims.width * dims.depth * f * (GEM_MATERIALS[material].sg / DIAMOND_SG)
}

/** Inverse of {@link gemCarat}: dimensions of a stone of the given carat weight. */
export function gemDimsFromCarat(
  cutId: GemCutId,
  carat: number,
  material: GemMaterialId = 'diamond',
  lw?: number,
): GemDims {
  const c: GemCut = GEM_CUTS[cutId]
  const ratio = Math.min(c.lw.max, Math.max(c.lw.min, lw ?? c.lw.default))
  const k = ratio * c.depthPct * caratFactor(c, ratio) * (GEM_MATERIALS[material].sg / DIAMOND_SG)
  return gemDims(cutId, Math.cbrt(carat / k), ratio)
}

/**
 * Stock melee diameters in mm (round). Pavé layouts snap to these so every stone in a design
 * can actually be sourced as a calibrated parcel.
 */
export const MELEE_SIZES_MM = [
  0.8, 0.9, 1.0, 1.1, 1.2, 1.25, 1.3, 1.4, 1.5, 1.6, 1.7, 1.75, 1.8, 1.9, 2.0, 2.1, 2.2, 2.25, 2.3,
  2.4, 2.5, 2.6, 2.7, 2.75, 2.8, 2.9, 3.0, 3.25, 3.5, 3.75, 4.0,
] as const

export function snapToMelee(diameter: number): number {
  let best: number = MELEE_SIZES_MM[0]
  for (const s of MELEE_SIZES_MM) if (Math.abs(s - diameter) < Math.abs(best - diameter)) best = s
  return best
}
